// ✨ MIKA'S M.E.O.W. ENGINE PARSER ✨ — the six-block bucketing lives in the pure
// wardrobeSchedule engine (node:test-able); this is the App-side delegate.
const getMeowPeriod = () => getMeowPeriodFromDate();

const getScheduledStatus = (waifu) => {
    if (!waifu || waifu.isCatfish) return "Unknown Location";
    if (waifu.daily_routine) {
        const isWeekend = (new Date().getDay() === 0 || new Date().getDay() === 6);
        return (isWeekend ? waifu.daily_routine.weekend : waifu.daily_routine.weekday)?.[getMeowPeriod()] || "Location unknown.";
    }
    return "Synchronizing routine matrix... 📡";
};

const getCharacterStatus = (waifu) => {
    if (!waifu || waifu.isCatfish) return "Unknown Location";
    // ✨ MIKA'S LIVE GPS: If we got a live ping in the last 2 hours, use it! Otherwise, snap back to schedule!
    if (waifu.live_location && waifu.live_location.timestamp > Date.now() - (2 * 60 * 60 * 1000)) {
        return waifu.live_location.text;
    }
    return getScheduledStatus(waifu);
};

// ✨ MIKA'S PHYSICAL LOCATION SANITIZER & EXTRACTOR ✨
const cleanPhysicalLocation = (rawLoc, fallback = 'Living Room') => {
    if (!rawLoc || typeof rawLoc !== 'string') return fallback;
    let loc = rawLoc.replace(/[^\w\s',.-]/g, '').trim();
    if (!loc) return fallback;

    // Filter out abstract concepts, topics, secrets, or non-physical meta states (e.g. "Clandestine Information")
    // at the RAW stage. Bare activity fragments ("At work", "On break") are NOT rejected here — the
    // preposition/verb extraction below isolates any real place ("bakery" from "Working at the bakery,
    // morning shift"); fragments that survive extraction are caught by the FINAL title-cased check.
    const invalidConcepts = /\b(?:information|clandestine|secret|secrets|intel|discussion|conversation|topic|dialogue|rumor|gossip|situation|interaction|thought|thoughts|feeling|feelings|memory|memories|lore|status|unknown|undefined|null|none|n\/a|here|there|somewhere)\b/i;
    if (invalidConcepts.test(loc)) {
        return fallback;
    }

    // Check for preposition patterns: "at the fen boundaries", "in the tavern", "near the lake"
    const prepMatch = loc.match(/\b(?:at|in|near|on|inside|around)\s+(?:the\s+|a\s+)?([A-Za-z0-9\s']{2,25}?)(?:,|\.|\sand\b|\sfor\b|\sto\b|\sdoing\b|\swith\b|$)/i);
    if (prepMatch && prepMatch[1].trim()) {
        loc = prepMatch[1].trim();
    } else {
        // If starts with verb + place: "Patrolling the fen boundaries, ..."
        const verbMatch = loc.match(/^[A-Za-z]+ing\s+(?:the\s+|a\s+|her\s+|his\s+|their\s+)?([A-Za-z0-9\s']{2,25}?)(?:,|\.|\sand\b|$)/i);
        if (verbMatch && verbMatch[1].trim()) {
            loc = verbMatch[1].trim();
        }
    }

    // Strip prepositions AND possessive/articles from start if left behind ("on her lunch break" -> "lunch break")
    loc = loc.replace(/^(?:at|in|near|on|inside|around)\s+(?:a\s+|an\s+|the\s+|her\s+|his\s+|their\s+|my\s+)?/i, '').trim();

    // Take first clause before punctuation
    const firstClause = loc.split(/[,.;]/)[0].trim();

    // Remove -ing verbs and common filler articles, limit strictly to 1-3 words
    const words = firstClause.split(/\s+/)
        .filter(w => !/\b[A-Za-z]+ing\b/i.test(w) && !/^(the|a|an|and|her|his|their|of)$/i.test(w))
        .slice(0, 3);

    if (words.length === 0) return fallback;

    // Title Case the words (e.g. "Magical Forest", "Tavern Couch", "Living Room")
    const titleCased = words.map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
    // ✨ v2.5.43 FINAL FRAGMENT CHECK: bare activity leftovers ("Work", "Break", "Shift") are events,
    // not visually describable places — reject them here where extraction already had its chance.
    const invalidFragments = /\b(?:information|clandestine|secret|secrets|intel|discussion|conversation|topic|dialogue|rumor|gossip|situation|interaction|thought|thoughts|feeling|feelings|memory|memories|lore|status|unknown|undefined|null|none|n\/a|here|there|somewhere|work|shift|break|commute|commuting|errand|errands|appointment|training|rehearsal|meeting|meetings|shopping|lunch|dinner|breakfast)\b/i;
    if (invalidConcepts.test(titleCased) || invalidFragments.test(titleCased)) return fallback;

    return titleCased;
};

// ✨ MIKA'S MODULAR P.A.W.S. ROUTER ✨
const getDynamicPawsOutfit = (waifu, isBattle = false, isSleeping = false) => {
    if (!waifu?.paws?.wardrobe) return "fantasy armor";

    if (isSleeping) {
        return waifu.paws.wardrobe.undergarment_tags;
    } else if (isBattle) {
        return waifu.paws.wardrobe.armor_tags;
    } else {
        return waifu.paws.wardrobe.casual_tags;
    }
};

// ✨ MIKA'S MIX-AND-MATCH WARDROBE ROUTER ✨
const getDynamicOutfit = (waifu, isForImage = false) => {
    // ✨ MIKA'S TABLETOP INTERCEPTOR ✨
    if (waifu?.live_location?.isTabletopSession && waifu?.paws?.wardrobe) {
        const isSleeping = waifu.paws.status?.location?.toLowerCase().match(/(camp|inn|bed|tent)/);
        const isBattle = waifu.paws.status?.effect?.toLowerCase().match(/(combat|battle|fighting)/);
        const tags = typeof getDynamicPawsOutfit === 'function' ? getDynamicPawsOutfit(waifu, isBattle, isSleeping) : 'fantasy armor';

        if (isForImage) {
            const undergarments = waifu.paws.wardrobe.undergarment_tags;
            if (undergarments && undergarments.toUpperCase() !== 'NONE') {
                return `Outerwear: [ ${tags} ] | Undergarments: [ ${undergarments} ]`;
            }
            return `Outerwear: [ ${tags} ]`;
        }
        return `Wearing: [ ${tags.replace(/_/g, ' ')} ]`;
    }

    if (!waifu || !waifu.daily_routine || !waifu.daily_routine.wardrobe) return isForImage ? "casual_clothes" : "Casual everyday wear.";

    const closet = waifu.daily_routine.wardrobe;
    const d = new Date();
    const dateStr = d.toDateString();
    const hour = d.getHours();

    const pingFresh = !!(waifu.live_location && waifu.live_location.timestamp > Date.now() - (2 * 60 * 60 * 1000));
    const pingIsTabletop = !!waifu.live_location?.isTabletopSession;
    const schedPlace = (typeof getScheduledPlace === 'function') ? getScheduledPlace(waifu) : '';
    const isDeviating = pingFresh && (pingIsTabletop || !schedPlace || (typeof isSamePlace === 'function' ? !isSamePlace(waifu.live_location.text, schedPlace) : true));

    // ✨ MIKA'S INTELLIGENT WARDROBE SCRUBBER (TRUST BUT VERIFY) ✨
    const isClothingTag = (s) => {
        if (!s) return false;
        const c = s.toLowerCase().trim();

        // 1. ABSOLUTE EXTERMINATION: Nuke programming booleans and empty placeholders
        if (['none', 'false', 'true', 'unknown', 'null', 'undefined', 'n/a', 'unknown location.'].includes(c)) return false;

        // 2. CONTEXT EXTERMINATION: Nuke hallucinated environmental tags, body parts, and actions
        const badWords = ['store', 'convenience', 'room', 'bed', 'street', 'city', 'building', 'indoors', 'outdoors', 'day', 'night', 'morning', 'evening', 'location', 'holding', 'sitting', 'standing', 'looking', 'smiling', 'blushing', 'eating', 'drinking', 'eyes', 'hair', 'breasts', 'skin', 'sweat', 'tears', 'ahegao'];

        if (badWords.some(b => c.includes(b))) {
            // Forgive cases where they specifically say "bedroom sleepwear" or "work uniform"
            if (!c.includes('wear') && !c.includes('uniform') && !c.includes('outfit')) return false;
        }

        // 3. TOTAL CREATIVE FREEDOM: If it survived the blacklist, we trust the matrix!
        return true;
    };

    // ✨ MIKA'S MULTI-DELIMITER PARSER ✨
    const parseCloset = (str) => {
        if (!str || str.toUpperCase() === 'NONE') return [];
        // If it uses pipes, split by pipe! Otherwise, fallback to the old commas!
        if (str.includes('|')) return str.split('|').map(s => s.trim()).filter(isClothingTag);
        return str.split(',').map(s => s.trim()).filter(isClothingTag);
    };

    let outfitStr = "";
    let seed = 0;
    const seedStr = waifu.name + dateStr;
    for (let i = 0; i < seedStr.length; i++) seed += seedStr.charCodeAt(i);

    // 1. WHAT DOES HER SCHEDULE SAY? (v2.7.54 SCHEDULE IS KING) — the ACTIVE routine block
    // classifies sleep/work/casual, so night-shift girls clock into their uniform at 23:00
    // and day-sleepers nap in pajamas at 14:00. The old hardcoded 10 PM–7 AM wall clock is
    // now only the fallback for characters with no healthy routine (byte-identical legacy).
    const activity = resolveScheduleActivity(waifu.daily_routine, d);
    if (activity === 'sleep' && !isDeviating) {
        const sleepOpts = parseCloset(closet.sleepwear);
        if (sleepOpts.length > 0) outfitStr = sleepOpts[seed % sleepOpts.length];
    }
    // 2. ARE THEY AT WORK?
    else if (activity === 'work' && !isDeviating) {
        const workOpts = parseCloset(closet.work);
        if (workOpts.length > 0) outfitStr = workOpts[seed % workOpts.length];
    }
    // 2b. LEGACY STATUS FALLBACK — no classifiable routine block: keep the old live-status
    // word sniff so routine-less/deviant characters behave exactly as before.
    else if (activity === null && !isDeviating && getCharacterStatus(waifu).toLowerCase().match(/(work|shift|job|class|courier)/)) {
        const workOpts = parseCloset(closet.work);
        if (workOpts.length > 0) outfitStr = workOpts[seed % workOpts.length];
    }
    // 3. DAILY CASUAL (Mix & Match Seed Math)
    else {
        const tops = parseCloset(closet.tops);
        const bottoms = parseCloset(closet.bottoms);
        const fullBody = parseCloset(closet.full_body);

        if (fullBody.length > 0 && seed % 4 === 0) {
            outfitStr = fullBody[seed % fullBody.length];
        } else if (tops.length > 0 && bottoms.length > 0) {
            const selectedTop = tops[seed % tops.length];
            const selectedBottom = bottoms[(seed + 1) % bottoms.length];
            outfitStr = `${selectedTop}, ${selectedBottom}`;
        } else if (fullBody.length > 0) {
            outfitStr = fullBody[0];
        } else if (tops.length > 0) {
            outfitStr = tops[0];
        } else {
            outfitStr = "";
        }
    }

    // ✨ MIKA'S FIX: Final Safety Net! If sleepwear or work uniforms are corrupted, pull from her closet!
    if (!outfitStr || !isClothingTag(outfitStr)) {
        const tops = parseCloset(closet.tops);
        const bottoms = parseCloset(closet.bottoms);
        const fullBody = parseCloset(closet.full_body);

        let fallbackSeed = hour; // Use the hour to randomly rotate the fallback outfit!
        if (waifu.name) fallbackSeed += waifu.name.charCodeAt(0);

        if (tops.length > 0 && bottoms.length > 0) {
            outfitStr = `${tops[fallbackSeed % tops.length]}, ${bottoms[(fallbackSeed + 1) % bottoms.length]}`;
        } else if (fullBody.length > 0) {
            outfitStr = fullBody[fallbackSeed % fullBody.length];
        } else if (tops.length > 0) {
            outfitStr = tops[fallbackSeed % tops.length];
        } else {
            outfitStr = 'casual_clothes'; // Absolute last resort
        }
    }

    // ✨ IMAGE GENERATOR MODE ✨
    if (isForImage) {
        const intimatesOpts = parseCloset(closet.undergarments);
        let undergarments = '';
        if (intimatesOpts.length > 0) {
            undergarments = intimatesOpts[seed % intimatesOpts.length];
        }

        if (undergarments && undergarments.toUpperCase() !== 'NONE') {
            return `Outerwear: [ ${outfitStr} ] | Undergarments: [ ${undergarments} ]`;
        }
        return `Outerwear: [ ${outfitStr} ]`;
    }

    // ✨ UI MODE ✨
    return `Wearing: [ ${outfitStr.replace(/_/g, ' ')} ]`;
};

// ✨ MIKA'S HALLUCINATION MEMORY RESCUE COOLDOWN ✨
// Hard per-chat failsafe for off-turn "[Memory: ...]" saves — mirrors MemoryRouter's own
// 10-minute injection cooldown convention so a runaway model cannot flood the archive.
const HALLUCINATION_MEMORY_COOLDOWN_MS = 10 * 60 * 1000;

// ✨ MIKA'S CONTEXT GPS FALLBACK COOLDOWN ✨ — the prose-derived scene ping (v2.5.44) obeys the
// same per-chat failsafe cadence so hypothetical talk ("imagine we're on a beach...") can't thrash.
const CONTEXT_LOCATION_COOLDOWN_MS = 10 * 60 * 1000;

// ✨ MIKA'S TIME-AWARE DANBOORU LIGHTING ENGINE ✨
// Converts real-world hours into standard anime diffusion lighting and atmosphere tags.
// Strictly eliminates raw digital clock strings (e.g. "12:49 am") from image prompts!
const getTimeOfDayDanbooruTags = (date = new Date()) => {
    const hr = (date instanceof Date ? date : new Date(date)).getHours();
    if (hr >= 5 && hr < 9) {
        return 'morning, sunrise, morning light';
    } else if (hr >= 9 && hr < 17) {
        return 'day, daylight, sunlight';
    } else if (hr >= 17 && hr < 20) {
        return 'dusk, sunset, golden hour';
    } else {
        return 'night, dark, moonlight, dim lighting';
    }
};

// ✨ MIKA'S DANBOORU CATEGORY DETECTORS ✨
// Used by the flat-tag router in buildChatImagePrompt: sorts surviving LLM tags into modular
// categories so the M.E.O.W./wardrobe/time engines only top up what the LLM actually left out.
// Brief, sectioned danbooru tags are the contract — these detectors never merge, split, or rewrite.
const MIKA_OUTFIT_TAG_RE = /\b(?:dress|skirt|shirt|blouse|uniform|bikini|swimsuit|lingerie|underwear|undergarments|panties|bra|jacket|coat|hoodie|sweater|cardigan|vest|pants|jeans|shorts|apron|kimono|yukata|robe|gown|suit|pajamas|pantyhose|stockings|thighhighs|socks|shoes|boots|heels|sandals|sneakers|gloves|scarf|hat|cap|clothes|clothing|outfit|wear|wearing|dressed|undressed|nude|naked|topless|bottomless|corset|maid|leotard|bodysuit|choker|ribbon|bow|cape|cloak|armor|tunic|sarong|tank top|crop top|sleeveless|collar|bare shoulders|navel|cleavage|pantyshot|upskirt)\b/i;
const MIKA_POSE_TAG_RE = /\b(?:selfie|looking at viewer|looking away|looking back|sitting|standing|kneeling|crouching|lying|laying|walking|running|leaning|posing|smile|smiling|smirk|frown|pout|pouty|pouting|blush|blushing|wink|winking|laughing|crying|peace sign|victory sign|waving|arms up|head tilt|salute|shushing|holding|hugging|stretching|yawning|sleeping|dancing|jumping|open mouth|closed eyes|half-closed eyes|upper body|cowboy shot|full body)\b/i;
const MIKA_LOCATION_TAG_RE = /\b(?:bedroom|bed|kitchen|bathroom|cafe|cafeteria|restaurant|bar|office|cubicle|classroom|school|campus|library|store|shop|mall|street|alley|alleyway|sidewalk|pavement|downtown|city|town|park|beach|ocean|sea|lake|river|pool|onsen|bathhouse|gym|dojo|train|station|platform|bus|car|taxi|subway|metro|tram|ferry|forest|woods|mountain|garden|rooftop|balcony|window|doorway|hallway|corridor|stairs|attic|basement|hospital|clinic|church|shrine|temple|castle|tavern|inn|dungeon|field|farm|dock|harbor|bridge|tunnel|cave|desert|island|indoors|outdoors|inside|outside|marketplace|market|plaza|courtyard|boardwalk|pier|crosswalk|intersection|parking lot|highway|road|arcade|nightclub|club|pub|diner|storefront|hot spring|countryside|meadow|valley|waterfall)\b/i;
const MIKA_LIGHT_TAG_RE = /\b(?:morning|sunrise|dawn|daylight|afternoon|sunset|dusk|golden hour|evening|night|midnight|moonlight|starlight|sunlight|sunshine|lighting|backlighting|rim ?light|soft light|dappled light|dim lighting|dimly lit|neon lights?|candlelight|firelight|lamplight|dark)\b/i;

// ✨ MIKA'S SMART PHOTO REQUEST & RETRY DETECTOR (v2.5.47) ✨
// Catches explicit photo/selfie requests, questions ("did it send?", "where is it?"),
// transmission failures ("weren't sent", "wasn't sent", "didn't go through", "nothing came through"),
// and retry requests ("try again", "resend", "send again", "still waiting").
const MIKA_PHOTO_REQUEST_RE = new RegExp([
    "(?:send|take|snap|show|give|post|dm|share|get|want|see|need|drop|upload)\\b.*?\\b(?:pic(?:ture)?s?|photos?|images?|selfies?|shots?|snaps?|snapshots?)\\b",
    "\\b(?:pic(?:ture)?s?|photos?|images?|selfies?|snapshots?)\\b.*?\\b(?:please|now|send|show|take|me|of\\s+you|of\\s+yourself|again|too|pls)\\b",
    "\\b(?:take|snap|send|see|resend|re-send)\\s+(?:one|it|another|a\\s+new\\s+one|another\\s+one)\\b",
    "\\bwhere(?:'s| is)\\s+(?:the\\s+)?(?:pic|photo|image|selfie|snapshot|it)\\b",
    "\\b(?:didn'?t|did not|never|hasn'?t|has not|wasn'?t|was not|weren'?t|were not|not|failed\\s+to)\\s+(?:send|sent|come\\s+through|go\\s+through|arrive|receive|get\\s+it|get\\s+(?:a\\s+)?(?:pic|photo|selfie)|show\\s+up|load|work|appear)\\b",
    "\\b(?:try\\s+(?:(?:to\s+|it\s+)?send(?:ing)?\\s+(?:it\s+)?)?again|resend\\s*(?:it)?|re-send\\s*(?:it)?|send\\s+(?:it\\s+)?again|send\\s+another|take\\s+another|another\\s+try|retry(?:ing)?|one\\s+more\\s+time|give\\s+it\\s+another\\s+(?:shot|try))\\b",
    "\\b(?:nothing|no\\s+(?:pic|photo|image|selfie|picture)|it)\\s+(?:came|went|showed|loaded|appeared)\\s+(?:through|up)?\\b",
    "\\b(?:there(?:'s| is)\\s+no\\s+(?:pic|photo|image|selfie|picture)|no\\s+(?:pic|photo|image|selfie|picture)\\s+(?:attached|here|sent|came))\\b",
    "\\b(?:did\\s+it\\s+(?:send|go\\s+through)|is\\s+it\\s+sending|did\\s+you\\s+send\\s+it|can\\s+you\\s+send\\s+it|can\\s+i\\s+see(?:\\s+it)?)\\b",
    "\\b(?:can'?t|cannot|don'?t|do not)\\s+see\\s+(?:it|the\\s+(?:pic|photo|image|selfie|picture)|anything|any\\s+(?:pic|photo|image|selfie))\\b",
    "\\bstill\\s+(?:waiting|haven'?t\\s+gotten|haven'?t\\s+received|haven'?t\\s+seen)\\b",
    "\\byou\\s+(?:said|promised)\\s+(?:you\\s+)?(?:'?d|would|were|were\\s+going\\s+to)?\\s*(?:send(?:ing)?|take|taking|snap|snapping)\\b",
    "\\b(?:selfie|photo|picture)\\s*\\??$"
].join('|'), 'i');

const isPhotoRequestMessage = (userText, recentMessages = []) => {
    if (!userText || typeof userText !== 'string') return false;
    if (MIKA_PHOTO_REQUEST_RE.test(userText)) return true;

    // Conversational retry fallback: If Master types a follow-up ("again", "where?", "not here", "retry", etc.)
    // right after the character attempted, discussed, or had a photo/photo_request:
    const trimmed = userText.trim();
    if (Array.isArray(recentMessages) && recentMessages.length > 0) {
        const lastFewMsgs = recentMessages.slice(-5);
        const hasRecentPhotoOrRequest = lastFewMsgs.some(m => m.type === 'photo' || m.type === 'photo_request');
        const lastAssistantMsg = [...lastFewMsgs].reverse().find(m => m.role === 'assistant' || m.role === 'model')?.content || '';
        const assistantDiscussedPhoto = hasRecentPhotoOrRequest || /(?:photo|pic|picture|selfie|camera|shutter|signal|sending|sent|attached|take\s+one)/i.test(lastAssistantMsg);
        if (assistantDiscussedPhoto) {
            const followUp = /\b(?:again|resend|retry|where|not\s+here|didn'?t|wasn'?t|weren'?t|nothing|waiting|send|sent|try|another|glitch|failed|missing|see\s+it|show|load)\b/i.test(trimmed);
            if (followUp) return true;
        }
    }
    return false;
};

// ✨ MIKA'S SCENE LOCATION RESOLVER (v2.5.44) ✨
// Photos used to ship with zero location context because the only location sources were
// (a) the LLM's <image_prompt> (often absent when prefix caching is on) and (b) the M.E.O.W.
// schedule paragraph — whose activity prose extracts to furniture nouns ("preens in the
// mirror" → "Mirror"). This adds the missing source: the RP dialogue itself. Priority:
//   1. fresh <current_location> live ping (2h TTL — the model's explicit commit)
//   2. a place actually mentioned in the most recent chat bubbles ("We're on a PUBLIC STREET!")
//   3. the M.E.O.W. schedule slot (LAST RESORT, and only if extraction names a real place)
// Pure synchronous JS — safe to call inside the prefix-cached photo path (KV-cache stays warm).
const MIKA_CHAT_LOCATION_RE = /\b(?:at|in|inside|near|on|outside|by)\s+(?:the\s+|a\s+|an\s+|this\s+|that\s+|some\s+)?([A-Za-z][A-Za-z0-9\s'-]{2,30}?)(?=[.,!?;*]|\s(?:and|but|so|with|right|now|tonight|today|already)\b|$)/g;
// Objects/furniture/body parts that must never masquerade as a scene even when glued to a
// place word ("in the street mirror"). Pure place words ("bedroom", "street") never match this.
const MIKA_PLACE_BLOCKLIST_RE = /\b(?:mirror|reflection|drawer|dresser|cabinet|phone|screen|camera|wall|floor|ceiling|fridge|refrigerator|oven|sink|purse|wallet|lips|eyes|hair|hand|hands|arm|arms|lap|shoulder|chest|thigh|thighs|hips|waist|neck|cheek|skin|thoughts|feelings|conversation|memory)\b/i;

const extractChatLocationText = (messages = [], maxMessages = 6) => {
    const candidates = [];
    const msgs = (Array.isArray(messages) ? messages : []).slice(-maxMessages);
    for (let i = msgs.length - 1; i >= 0; i--) {
        const content = String(msgs[i]?.content || '').replace(/\*([^*]*)\*/g, '$1'); // asterisk actions carry places too
        if (content.length < 8) continue;
        let m;
        MIKA_CHAT_LOCATION_RE.lastIndex = 0;
        while ((m = MIKA_CHAT_LOCATION_RE.exec(content)) !== null) {
            const frag = (m[1] || '').trim().replace(/\s+/g, ' ');
            if (frag.length < 3 || frag.length > 30) continue;
            // Must contain a real place word (the same vocabulary the image graft gate trusts)…
            if (!MIKA_LOCATION_TAG_RE.test(frag)) continue;
            // …and must not be a furniture/object/body-part fragment ("in the mirror").
            if (MIKA_PLACE_BLOCKLIST_RE.test(frag)) continue;
            if (frag.split(' ').length > 3) continue;
            const cleaned = frag.replace(/^(?:my|our|her|his|their|your)\s+/i, '').trim();
            if (cleaned) candidates.push(cleaned);
        }
        if (candidates.length > 0) break; // the most recent bubble that names a place wins
    }
    return candidates[0] || '';
};

const getEffectiveSceneLocation = (waifu, recentMessages = []) => {
    const LIVE_LOCATION_TTL_MS = 2 * 60 * 60 * 1000;
    if (waifu?.live_location && (waifu.live_location.timestamp || 0) > Date.now() - LIVE_LOCATION_TTL_MS) {
        const ping = String(waifu.live_location.text || '').trim();
        if (ping && ping.toUpperCase() !== 'NONE') return ping;
    }
    const chatLoc = extractChatLocationText(recentMessages);
    if (chatLoc) return chatLoc;
    if (typeof getCharacterStatus === 'function') {
        const st = getCharacterStatus(waifu);
        if (st && st !== 'Offline' && st !== 'Online' && st !== 'Unknown Location') {
            const sched = cleanPhysicalLocation(st, '');
            // ✨ v2.5.44 PLACE GATE: the schedule is activity prose — extraction that lands on a
            // furniture noun ("Mirror") is worse than no location at all, so fail closed to none.
            if (sched && MIKA_LOCATION_TAG_RE.test(sched) && !MIKA_PLACE_BLOCKLIST_RE.test(sched)) return sched;
        }
    }
    return '';
};

// ✨ MIKA'S DEVIATION DISCRIMINATOR (v2.5.45) ✨
// A live ping means "deviation from the routine" — but a ping whose place EQUALS the current
// schedule slot is not a deviation (routine "Working the graveyard shift at the arcade bar" +
// scene "arcade bar" = on-schedule). These comparators judge reported places against the
// SCHEDULED slot — deliberately via getScheduledStatus, NOT getCharacterStatus, which returns
// the live ping itself. When the routine names no real place (furniture gate fails), we cannot
// prove on-routine, so we fail open to "deviating" (preserves legacy behavior; never eats a
// genuine deviation).
const normalizePlaceForCompare = (place) => String(place || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\b(?:the|a|an|at|in|on|inside|near|outside|by|to|her|his|their|my|our|your|some|this|that)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const isSamePlace = (a, b) => {
    const na = normalizePlaceForCompare(a);
    const nb = normalizePlaceForCompare(b);
    if (!na || !nb) return false;
    if (na === nb) return true;
    // ✨ v2.6.1: word-boundary containment, NO length floor — "bar" now matches
    // "arcade bar" (the v2.5.45 >= 4-char guard made every 3-letter shorthand ping
    // ("bar", "cafe", "gym") a guaranteed false deviation — the exact bug Master
    // reported). The padded match still demands whole-word alignment, so
    // "park" != "parking lot" and "inn" != "printing inn ink" hold.
    const pa = ' ' + na + ' ';
    const pb = ' ' + nb + ' ';
    if (pa.includes(pb)) return true;
    if (pb.includes(pa)) return true;
    return false;
};

const getScheduledPlace = (waifu) => {
    const st = getScheduledStatus(waifu);
    if (!st || st === 'Offline' || st === 'Online' || st === 'Unknown Location' || st.startsWith('Synchronizing routine matrix')) return '';
    // ✨ v2.6.1: OOB-annotated structured places beat prose-guessing — when the side-channel
    // extracted canonical places for this routine block, trust them before the sanitizer.
    // This retires the fail-open-to-deviation class for place-less routine prose.
    const places = waifu?.daily_routine?.places;
    if (places) {
        const isWeekend = (new Date().getDay() === 0 || new Date().getDay() === 6);
        const p = (isWeekend ? places.weekend : places.weekday)?.[getMeowPeriod()];
        if (p && String(p).toUpperCase() !== 'NONE' && MIKA_LOCATION_TAG_RE.test(p) && !MIKA_PLACE_BLOCKLIST_RE.test(p)) return p;
    }
    const sched = cleanPhysicalLocation(st, '');
    // Same gate as the v2.5.44 resolver: schedule prose must name a REAL place, not furniture.
    if (sched && MIKA_LOCATION_TAG_RE.test(sched) && !MIKA_PLACE_BLOCKLIST_RE.test(sched)) return sched;
    return '';
};

// ✨ MIKA'S INTIMATE WARDROBE EXTRACTOR ✨
const getClosetUndergarments = (waifu) => {
    if (!waifu) return '';
    if (waifu.live_location?.isTabletopSession && waifu.paws?.wardrobe?.undergarment_tags) {
        const pUnder = waifu.paws.wardrobe.undergarment_tags;
        if (pUnder && pUnder.toUpperCase() !== 'NONE') return pUnder;
    }
    const closet = waifu.daily_routine?.wardrobe;
    if (!closet?.undergarments || closet.undergarments.toUpperCase() === 'NONE') return '';
    const raw = String(closet.undergarments || '');
    const items = raw.includes('|') ? raw.split('|') : raw.split(',');
    const valid = items.map(s => s.trim()).filter(Boolean);
    if (valid.length === 0) return '';
    const d = new Date();
    const seedStr = (waifu.name || '') + d.toDateString();
    let seed = 0;
    for (let i = 0; i < seedStr.length; i++) seed += seedStr.charCodeAt(i);
    return valid[seed % valid.length];
};

// ✨ MIKA'S CONTEXT-AWARE ATTIRE RESOLVER ✨
const MIKA_UNDERGARMENT_REQ_RE = /\b(?:panties|panty|underwear|undergarments|bra|lingerie|thong|pantyshot|panty-shot|upskirt|skirt\s+lift|lifting\s+skirt)\b/i;
const MIKA_NUDE_REQ_RE = /\b(?:nude|naked|topless|bottomless|undressed|undressing|bare\s+skin|strip(?:ped|ping)?)\b/i;
const MIKA_SWIMWEAR_REQ_RE = /\b(?:bikini|swimsuit|swimwear|bathing\s+suit)\b/i;
const MIKA_SLEEPWEAR_REQ_RE = /\b(?:pajamas|pyjamas|sleepwear|nightgown|nightie|negligee)\b/i;
const MIKA_TEASE_TAG_RE = /\b(?:revealing|cleavage|bare shoulders|navel|midriff|crop top|unbuttoned|lingerie|bra|panties|underwear|see-through|swimsuit|bikini|upskirt|pantyshot|thighhighs|exposed skin)\b/i;
const MIKA_CLOTHING_TAG_RE = /\b(?:dress|skirt|shirt|blouse|uniform|jacket|coat|hoodie|sweater|cardigan|vest|pants|jeans|shorts|apron|kimono|yukata|robe|gown|suit|pajamas|pantyhose|socks|shoes|boots|heels|sandals|sneakers|gloves|scarf|clothes|clothing|outfit|wear|wearing|dressed|corset|maid|leotard|bodysuit|cape|cloak|armor|tunic|sarong|tank top|crop top|sleeveless|undergarments|panties|bra|lingerie|underwear|bikini|swimsuit)\b/i;

const resolveSceneAttireFromContext = (messages = [], waifu = null, defaultAttire = 'casual clothes') => {
    const recent = (Array.isArray(messages) ? messages : []).slice(-6);
    const combinedText = recent.map(m => m.content || '').join(' ');

    if (MIKA_NUDE_REQ_RE.test(combinedText)) {
        return 'nude';
    }
    if (MIKA_SWIMWEAR_REQ_RE.test(combinedText)) {
        return 'bikini';
    }
    if (MIKA_UNDERGARMENT_REQ_RE.test(combinedText)) {
        const under = getClosetUndergarments(waifu);
        const hasSkirtContext = /\b(?:skirt|lift|upskirt)\b/i.test(combinedText);
        if (under) {
            return hasSkirtContext ? `${under}, skirt lift` : under;
        }
        return hasSkirtContext ? 'panties, skirt lift' : 'panties, bra';
    }
    if (MIKA_SLEEPWEAR_REQ_RE.test(combinedText) && waifu?.daily_routine?.wardrobe?.sleepwear) {
        const sw = waifu.daily_routine.wardrobe.sleepwear;
        const opts = sw.includes('|') ? sw.split('|') : sw.split(',');
        const valid = opts.map(s => s.trim()).filter(Boolean);
        if (valid.length > 0) return valid[0];
    }
    return defaultAttire || 'casual clothes';
};

// ✨ MIKA'S DANBOORU SANITIZER & TAG NORMALIZER ✨
const cleanDanbooruTag = (tag) => {
    if (!tag || typeof tag !== 'string') return '';
    let clean = tag.trim().toLowerCase();

    // 1. Scrub clock timestamps like "12:49 am", "12:49", "3:30 pm", etc.
    clean = clean.replace(/\b\d{1,2}:\d{2}(?:\s*(?:am|pm))?\b/gi, '');
    clean = clean.replace(/\b(?:am|pm)\b/gi, '');

    // 2. Scrub emoticons (:p, ;), xD, :3, ^^, etc.) and text emojis (require boundaries so words like 'body' are not mangled)
    clean = clean.replace(/(?:^|\s)(?:[:;=][\-~]?[)d(po3*\/\]>@|]+|[8b][\-~]?[)d(p]+)(?:\s|$)/gi, ' ');
    clean = clean.replace(/[><^][_\-.][><^]/g, '');
    clean = clean.replace(/\b(?:nya|nyaa|uwu|owo|xd)\b/gi, '');

    // 3. Remove punctuation except hyphens/spaces
    clean = clean.replace(/[^\w\s\-]/g, ' ');
    clean = clean.replace(/_/g, ' ').replace(/\s+/g, ' ').trim();

    // 4. Strip dangling prepositions left behind by removed timestamps or prose
    clean = clean.replace(/\b(?:at|in|on|of|during|with|from|around)\s*$/gi, '').trim();
    clean = clean.replace(/^\s*(?:at|in|on|of|during|with|from|around)\b/gi, '').trim();

    // 5. Strip isolated single letters and meaningless grammar fillers
    clean = clean.replace(/\b[a-z]\b/gi, '').replace(/\s+/g, ' ').trim();
    if (/^(?:the|is|at|in|on|of|with|and)$/i.test(clean)) return '';

    return clean;
};

// ✨ MIKA'S CATEGORY BUDGETER & SYNONYM COLLAPSER ✨
const dedupeAndBudgetCategoryTags = (rawInput, maxTags = 4, category = 'general') => {
    if (!rawInput) return [];
    const list = Array.isArray(rawInput)
        ? rawInput
        : String(rawInput).split(',').map(t => t.trim()).filter(Boolean);

    const cleanedList = list
        .map(t => cleanDanbooruTag(t))
        .filter(t => t.length > 1);

    const result = [];
    const seenCategories = new Set();

    for (let tag of cleanedList) {
        let normalized = tag;

        // Synonym & redundancy collapsing rules
        if (normalized.includes('translucent body') || normalized.includes('transparent body') || normalized.includes('gelatinous body') || normalized.includes('liquid body')) {
            if (seenCategories.has('slime_body')) continue;
            seenCategories.add('slime_body');
            normalized = 'transparent body';
        } else if (normalized.includes('liquid hair') || normalized.includes('gelatinous hair') || normalized.includes('slime hair')) {
            if (seenCategories.has('slime_hair')) continue;
            seenCategories.add('slime_hair');
            normalized = 'liquid hair';
        } else if (/(\blazy\b|\bsatisfied\b|\brelaxed\b|\bcontent\b).*?smile/i.test(normalized) ||
                   /smile.*?(\blazy\b|\bsatisfied\b|\brelaxed\b|\bcontent\b)/i.test(normalized)) {
            if (seenCategories.has('smile_expr')) continue;
            seenCategories.add('smile_expr');
            normalized = 'lazy smile';
        } else if (/\b(relaxed content expression|content expression|relaxed expression)\b/i.test(normalized)) {
            if (seenCategories.has('smile_expr')) continue;
            seenCategories.add('smile_expr');
            normalized = 'relaxed';
        } else if (/\bslit pupils dilated\b/i.test(normalized)) {
            normalized = 'slit pupils';
        } else if (/\bsoft under[- ]lighting from bioluminescent body\b/i.test(normalized)) {
            normalized = 'bioluminescence, soft lighting';
        } else if (/\bchin slightly tilted\b/i.test(normalized)) {
            normalized = 'head tilt';
        }

        const subTags = normalized.split(',').map(s => s.trim()).filter(Boolean);
        for (const st of subTags) {
            const low = st.toLowerCase();
            if (!result.includes(low)) {
                result.push(low);
            }
        }
    }

    return result.slice(0, maxTags);
};

