    const activeDonorDelta = Math.max(0, activeImageBudgets.prefix - activeTierTable.prefix) + Math.max(0, activeImageBudgets.core - activeTierTable.core);
    const activeBudgetTotal = deepEconomyTotal(activeDeepPromptPrefs.budget) + activeDonorDelta;
