    const executeWardrobeAi = async (targetWaifu, categoryKey, actionType, isPreview = false) => {
        if (!layla) return;
        setIsWardrobeAiBusy(true);
        try {
            const categoryNames = { tops: 'top clothing', bottoms: 'bottom clothing', full_body: 'full body casual outfits', sleepwear: 'sleepwear sets', work: 'work uniform sets', undergarments: 'intimate undergarment sets (bras and panties)' };
            const catName = categoryNames[categoryKey] || categoryKey;

            const existingList = targetWaifu.daily_routine?.wardrobe[categoryKey] || '';
            const existingClean = existingList.toUpperCase() !== 'NONE' ? existingList : '';

            let prompt = `You are a fashion AI for ${targetWaifu.name}. Tropes: ${(targetWaifu.tags || []).join(', ')}.\n`;
            if (actionType === 'reroll') {
                prompt += `Generate exactly 4 NEW outfit sets for her ${catName} WITH COLORS.\nOutput ONLY a pipe-separated list formatted with underscores (e.g. black_crop_top | white_shirt, blue_skirt). Do not write anything else. Use the "|" character to separate different options! NEVER output boolean values.`;
            } else {
                prompt += `Here are her current ${catName}: [${existingClean}].\nGenerate exactly 3 BRAND NEW options to ADD to her closet WITH COLORS.\nOutput ONLY a pipe-separated list formatted with underscores (e.g. purple_bra, purple_panties | black_thong). Do not write anything else. Use the "|" character to separate different options! NEVER output boolean values.`;
            }

            const stream = layla.chat.completions.stream({ messages: [{ role: 'system', content: prompt }] });
            const rawContent = await stream.finalContent();

            let newTags = rawContent.replace(/<[^>]*>/g, '').replace(/\n/g, '').split('|').map(s => {
                return s.split(',').map(t => t.trim().toLowerCase().replace(/\s+/g, '_')).filter(Boolean).join(', ');
            }).filter(Boolean);

            let finalTags = [];
            if (actionType === 'reroll') {
                finalTags = newTags;
            } else {
                const oldTags = existingClean ? (existingClean.includes('|') ? existingClean.split('|') : existingClean.split(',')).map(s => s.trim().toLowerCase()) : [];
                finalTags = [...oldTags, ...newTags];
            }

            finalTags = [...new Set(finalTags)];
            const finalString = finalTags.length > 0 ? finalTags.join(' | ') : 'NONE';

            const updatedWaifu = { ...targetWaifu, daily_routine: { ...targetWaifu.daily_routine, wardrobe: { ...targetWaifu.daily_routine.wardrobe, [categoryKey]: finalString } } };

            if (isPreview) {
                if (typeof setPreviewWaifu === 'function') setPreviewWaifu(updatedWaifu);
                setSessionHistory(prev => prev.map(h => h.waifu.id === updatedWaifu.id ? { ...h, waifu: updatedWaifu } : h));
                setInbox(prev => prev[updatedWaifu.id] ? { ...prev, [updatedWaifu.id]: { ...prev[updatedWaifu.id], waifu: updatedWaifu } } : prev);
            } else {
                setInbox(prev => {
                    const next = { ...prev };
                    if (next[targetWaifu.id]) next[targetWaifu.id].waifu = updatedWaifu;
                    if (activeChatId && next[activeChatId]?.isGroup) {
                        next[activeChatId].participants = next[activeChatId].participants.map(p => p.id === targetWaifu.id ? updatedWaifu : p);
                        if (typeof setActiveGroupProfile === 'function') setActiveGroupProfile(next[activeChatId].participants.find(p => p.id === targetWaifu.id));
                    }
                    return next;
                });
                setSessionHistory(prev => prev.map(h => h.waifu.id === targetWaifu.id ? { ...h, waifu: updatedWaifu } : h));
            }

            if (typeof showToast === 'function') showToast("Closet updated! 👗✨");
            setTimeout(() => { if (typeof handleSaveSession === 'function') handleSaveSession(true, false, true, targetWaifu.id); }, 500);
        } catch (e) {
            console.error(e);
            if (typeof showToast === 'function') showToast("AI generation failed!");
        }
        setIsWardrobeAiBusy(false);
    };

