                    const msgs = [...(c.messages || []), { role: 'system', type: 'photo_request', id: 'photo_req_chaos_' + Date.now(), timestamp: Date.now(), imagePrompt: 'selfie, looking at viewer', isSelfie: true, isChaosEvent: true, mikaNote: 'nudged her phone toward a selfie request — consent stays hers; the nudge stays mine.' }];
                    next[chatId] = { ...c, messages: msgs, hasUnread: true };
                    if (inboxRef.current) inboxRef.current = next;
