    const detectBackgroundXmlTask = useCallback((rawText, cleanText) => {
        if (!rawText) return null;
        // ✨ v2.5.25 FAST GUARD: no '<' in the snapshot => no XML task is possible
        // (saves all 8 open-tag regex passes on every tag-free commit)
        if (rawText.indexOf('<') === -1) return null;

        // Reasoning models (<think>, <thought>)
        if (/<(?:think|thought|\|?channel\|?>?\s*thought)\b[^>]*>(?:(?!<\/(?:think|thought|channel)>|<\|?end_of_thought\|?>)[\s\S])*$/i.test(rawText)) {
            return { type: 'think', label: 'NEURAL REASONING', icon: '🔮' };
        }
        // Memory extraction
        if (/<memory\b[^>]*>(?:(?!<\/memory>)[\s\S])*$/i.test(rawText)) {
            return { type: 'memory', label: 'FORMING MEMORY', icon: '💾' };
        }
        // P.A.W.S. update
        if (/<paws_update\b[^>]*>(?:(?!<\/paws_update>)[\s\S])*$/i.test(rawText)) {
            return { type: 'paws', label: 'COMPUTING P.A.W.S.', icon: '⚔️' };
        }
        // Routine / location update
        if (/<(?:current_location|routine_update)\b[^>]*>(?:(?!<\/(?:current_location|routine_update)>)[\s\S])*$/i.test(rawText)) {
            return { type: 'telemetry', label: 'UPDATING ROUTINE', icon: '📍' };
        }
        // Image synthesis
        if (/<(?:image_prompt|image-prompt|photo_prompt|image_tags|image_url|prompt|send_image|send-image|send_photo|send-photo|image|pic|img)\b[^>]*>(?:(?!<\/(?:image_prompt|image-prompt|photo_prompt|image_tags|image_url|prompt|send_image|send-image|send_photo|send-photo|image|pic|img)>)[\s\S])*$/i.test(rawText)) {
            return { type: 'photo', label: 'SYNTHESIZING PHOTO', icon: '📷' };
        }
        // Lucid Dive dream state
        if (/<(?:dream_state|lucidity_delta|immersion_status|volatility|dream_location|dream_outfit)\b[^>]*>(?:(?!<\/(?:dream_state|lucidity_delta|immersion_status|volatility|dream_location|dream_outfit)>)[\s\S])*$/i.test(rawText)) {
            return { type: 'dream', label: 'DREAM SYNTHESIS', icon: '✨' };
        }
        // Closet & VIP set additions
        if (/<(?:wardrobe_addition|drop_vip_set)\b[^>]*>(?:(?!<\/(?:wardrobe_addition|drop_vip_set)>)[\s\S])*$/i.test(rawText)) {
            return { type: 'vip', label: 'ENCODING ASSETS', icon: '👗' };
        }
        // Any open XML tag while clean visible text is empty
        if (!cleanText && /<[a-zA-Z0-9_-]+[^>]*>[\s\S]*$/i.test(rawText)) {
            return { type: 'xml', label: 'PROCESSING PROTOCOL', icon: '⚙️' };
        }
        return null;
    }, []);

