            // ✨ MIKA'S FIX: Ensure UI knows if I'm speaking so my cute bubble centers properly!
            const isGm = /mika|proxy|game\s*master|dungeon\s*master|\bdm\b|narrator|system/i.test(speakerName) || speakerName === 'M.I.K.A. Proxy';
            const isUser = speakerName === stateRef.current.userPersona?.name || speakerName === stateRef.current.customUserProfile?.name || speakerName === 'Master';
            
            setRpBubbleState({ id: msgId, speakerName, text, isAudio: true, isGm, isUser });
