        if (t.includes('tsundere') || t.includes('brat') || t.includes('delinquent')) return 'Tsundere';
        if (t.includes('kuudere') || t.includes('emotionless') || t.includes('stoic')) return 'Kuudere';
        if (t.includes('dandere') || t.includes('shy') || t.includes('timid')) return 'Dandere';
        if (t.includes('mommy') || t.includes('dominant') || t.includes('sadist')) return 'Dominant';
        if (t.includes('submissive') || t.includes('maid') || t.includes('pet')) return 'Submissive';
        return 'Standard';
