    const [isGroupSpooling, setIsGroupSpooling] = useState(false); // ✨ MIKA'S LLM ACTIVE STATE
    const [groupSpoolStatus, setGroupSpoolStatus] = useState(null); // ✨ MIKA'S LIVE SPOOL STATUS (PREFILL / GEN / RETRY)

    // ✨ MIKA'S LIVE SPOOL TIMER TICKER ✨
    useEffect(() => {
        if (!isGroupSpooling && !groupSpoolStatus) return;
        const timer = setInterval(() => {
            setGroupSpoolStatus(prev => {
                if (!prev) return prev;
                if (prev.stage === 'retry') {
                    const nextSec = Math.max(0, (prev.retrySec || 1) - 1);
                    // ✨ v2.5.33: retire the retry badge at zero ✨ — the old ticker kept emitting a
                    // fresh object every second forever when the re-arm guard never fired (e.g.
                    // after leaving the chat): a permanent 1Hz app-wide re-render loop.
                    if (nextSec <= 0) return null;
                    return { ...prev, retrySec: nextSec };
                }
                const elapsed = Math.round((Date.now() - (prev.startTime || Date.now())) / 1000);
                return { ...prev, elapsedSec: elapsed };
            });
        }, 1000);
        return () => clearInterval(timer);
    }, [isGroupSpooling, groupSpoolStatus?.stage]);

    // ✨ MIKA'S 1-ON-1 PREFILL % TICKER (v2.5.26) ✨ — mirrors the group spool ticker
