                    let baseInAppDelay = 300000; // Default: 5 mins

                    if (/yandere|clingy|obsessive|possessive/.test(tags)) baseInAppDelay = 120000; // 2 mins
                    else if (/tsundere|impatient/.test(tags)) baseInAppDelay = 240000; // 4 mins
                    else if (/kuudere|shy|dandere/.test(tags)) baseInAppDelay = 600000; // 10 mins

                    if (aff > 80) baseInAppDelay *= 0.5;
                    else if (aff < 20) baseInAppDelay *= 1.5;

                    let idleMs = isStaring ? baseInAppDelay : (baseInAppDelay * 2.5);

                    if (consecutiveIdles > 0) {
                        idleMs += consecutiveIdles * (isStaring ? 300000 : 600000); // Adds 5 to 10 minutes of backoff per strike!
                    }

