    const handlePositionPackImport = async (e) => {
        const file = e?.target?.files?.[0];
        if (!file) return;
        try {
            const parsed = JSON.parse(await file.text());
            let candidates = [];
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && Array.isArray(parsed.positions)) candidates = [parsed];
            else if (Array.isArray(parsed)) candidates = parsed.filter((p) => p && typeof p === 'object' && Array.isArray(p.positions));
            else if (parsed && typeof parsed === 'object') candidates = Object.values(parsed).filter((p) => p && typeof p === 'object' && Array.isArray(p.positions));
            if (candidates.length === 0) { showToast('No position packs found in that file! 🚫'); e.target.value = ''; return; }
            const importedPacks = [];
            let totalSkipped = 0;
            candidates.forEach((cand) => {
                const v = validatePositionPack(cand);
                if (!v.ok) return;
                totalSkipped += v.skipped;
                importedPacks.push({ id: cand.id || `pospack_${v.theme}_${Date.now()}`, name: v.name, theme: v.theme, enabled: cand.enabled !== false, builtin: false, positions: v.positions });
            });
            if (importedPacks.length === 0) { showToast('Every pack failed validation! 🚫'); e.target.value = ''; return; }
            setPositionPacks((prev) => {
                const next = [...prev];
                importedPacks.forEach((p) => {
                    let id = p.id;
                    while (next.some((x) => x.id === id)) id = `${id}_${Date.now()}`;
                    next.push({ ...p, id });
                });
                return next;
            });
            showToast(`Imported ${importedPacks.length} pack(s)!${totalSkipped ? ` (${totalSkipped} invalid positions skipped)` : ''} 🐾`);
        } catch (err) {
            console.error('[POSITION] import failed', err);
            showToast('Import failed — invalid JSON! 🚫');
        }
        e.target.value = '';
    };

