    // ✨ MIKA'S THEME PACK IMPORT & EXPORT ENGINE ✨
    const triggerJsonDownload = async (filename, contentStr) => {
        // ✨ MIKA'S FIX: Strip any forbidden filesystem characters from filename (e.g. colons in "Star Wars: Clone Wars" or slashes in "Fate/Stay")
        const safeFilename = (filename || 'theme.json').replace(/[/\\?%*:|"<>]/g, '_');
        const activeLayla = window.layla || layla;
        if (activeLayla?.utils?.saveFile) {
            try {
                await activeLayla.utils.saveFile(safeFilename, encodeBase64Safe(contentStr), true);
                return;
            } catch (nativeErr) {
                console.warn("[M.I.K.A.] Layla saveFile failed, falling back to Blob download", nativeErr);
            }
        }
        const blob = new Blob([contentStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = safeFilename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

