    const handleThemeImport = async (event) => {
        const file = event.target?.files?.[0];
        if (!file) return;

        try {
            const text = await file.text();
            let parsed = JSON.parse(text);

            let importedList = [];
            if (parsed && typeof parsed === 'object') {
                if (parsed.label && (Array.isArray(parsed.buttons) || parsed.buttons)) {
                    importedList = [parsed];
                } else if (Array.isArray(parsed)) {
                    importedList = parsed.filter(t => t && t.label && (Array.isArray(t.buttons) || t.buttons));
                } else {
                    const vals = Object.values(parsed);
                    importedList = vals.filter(t => t && typeof t === 'object' && t.label && (Array.isArray(t.buttons) || t.buttons));
                }
            }

            if (importedList.length === 0) {
                showToast("Invalid theme file! Must contain 'label' and 'buttons'. 🚫");
                return;
            }

            const newThemes = {};
            let lastLabel = '';

            importedList.forEach((themeData, idx) => {
                const uniqueId = importedList.length === 1 ? ('custom_' + Date.now()) : ('custom_' + Date.now() + '_' + idx);
                const buttons = Array.isArray(themeData.buttons) ? themeData.buttons : [];
                const axes = Array.isArray(themeData.axes) ? themeData.axes : [];
                const quirks = Array.isArray(themeData.quirks) ? themeData.quirks : [];
                const degenQuirks = Array.isArray(themeData.degen_quirks) ? themeData.degen_quirks : [];
                const refList = Array.isArray(themeData.reference_list) ? themeData.reference_list : buttons;
                // ✨ MIKA'S FIX: Robust canon character parsing across known alias keys!
                const refChars = Array.isArray(themeData.reference_chars)
                    ? themeData.reference_chars
                    : (Array.isArray(themeData.known_characters)
                        ? themeData.known_characters
                        : (Array.isArray(themeData.canonical_characters)
                            ? themeData.canonical_characters
                            : (Array.isArray(themeData.canon_characters)
                                ? themeData.canon_characters
                                : (Array.isArray(themeData.characters) ? themeData.characters : []))));
                const franchiseAnchor = themeData.franchise_anchor || themeData.franchise || themeData.franchise_name || themeData.series || null;

                const cleanTheme = {
                    ...themeData,
                    id: uniqueId,
                    label: (themeData.label || 'Imported Theme').trim(),
                    buttons,
                    axes,
                    quirks,
                    degen_quirks: degenQuirks,
                    reference_list: refList,
                    reference_chars: refChars,
                    franchise_anchor: franchiseAnchor,
                    themeMode: franchiseAnchor || refChars.length > 0 ? 'franchise' : 'original',
                    enabled: themeData.enabled !== undefined ? themeData.enabled : true,
                    isCustom: true
                };
                delete cleanTheme._LLM_INSTRUCTIONS_;
                newThemes[uniqueId] = cleanTheme;
                lastLabel = cleanTheme.label;
            });

            setThemes(prev => {
                const next = { ...prev, ...newThemes };
                if (stateRef.current) {
                    stateRef.current.themes = next;
                }
                return next;
            });

            if (importedList.length === 1) {
                showToast(`Theme '${lastLabel}' imported! 🐾✨`);
            } else {
                showToast(`Imported ${importedList.length} themes! 🐾✨`);
            }

            setTimeout(() => {
                handleSaveSession(true, false, false);
            }, 300);

        } catch (err) {
            console.error("[M.I.K.A.] Theme import failed", err);
            showToast("Failed to parse theme file! 🚫");
        } finally {
            if (event.target) event.target.value = '';
        }
    };

