    const handleShareProfile = async (friendId, matchWaifu) => {
        setIsShareMenuOpen(false);
        setProfileToShare(null);
        setShowMatchProfile(false);

        const friendChat = inbox[friendId];
        if (!friendChat || !matchWaifu || !layla) return;

        const friendName = friendChat.waifu?.name || friendChat.name || 'Friend';
        const matchName = matchWaifu.name || 'Unknown';
        const matchDetails = `Tropes: ${matchWaifu.tags?.join(', ') || 'None'}. Personality: ${matchWaifu.personality || 'Unknown'}. Quirks: ${matchWaifu.quirks?.join(', ') || 'None'}.`;

        const activeUserName = useLaylaPersona ? (userPersona.name || 'Master') : (customUserProfile.name || 'Master');
        const userMsg = `*${activeUserName} shared a profile: [Link to ${matchName}]*`;

        setInbox(prev => ({
            ...prev,
            [friendId]: {
                ...prev[friendId],
                messages: [...prev[friendId].messages, { role: 'user', content: userMsg, timestamp: Date.now() }],
                hasUnread: false
            }
        }));

        setIsBuddyTyping(true);
        setAppState('swipe');
        setActiveChatId(friendId);
        setIsBuddyOpen(true);

        const sysPrompt = `[SYSTEM: SMS SIMULATION MODE]\nYou are ${friendName}. ${activeUserName} just texted you a screenshot of a girl they saw on a dating app named ${matchName}.\n\nGirl's Profile Details:\n${matchDetails}\n\nCRITICAL RULES:\n1. Give your honest, jealous, or supportive opinion on her.\n2. Base your reaction heavily on your own personality and tropes.\n3. Output ONLY the literal text message. No roleplay or asterisks.\n4. Keep it brief (1-2 sentences).`;

        try {
            const stream = layla.chat.completions.stream({ messages: [{ role: 'system', content: sysPrompt }] });
            setInbox(prev => ({ ...prev, [friendId]: { ...prev[friendId], messages: [...prev[friendId].messages, { role: 'assistant', content: '', timestamp: Date.now() }] } }));

            stream.on('content', (delta, snapshot) => {
                const cleanSnap = snapshot.replace(/<[\/\\]?(?:think|thought|\|?channel\|?>?\s*thought|channel>thought)\b>?[\s\S]*?(?:<[\/\\]?(?:think|thought|channel)>|<\|?end_of_thought\|?>|<\|?channel\|?>?\s*(?:model|assistant|bot|message))/gi, '').replace(/<[\/\\]?(?:think|thought|\|?channel\|?>?\s*thought|channel>thought)\b>?[\s\S]*$/gi, '').replace(/<[^>]*>?/g, '').trim();
                setInbox(prev => {
                    const msgs = [...prev[friendId].messages];
                    msgs[msgs.length - 1] = { ...msgs[msgs.length - 1], content: cleanSnap };
                    return { ...prev, [friendId]: { ...prev[friendId], messages: msgs } };
                });
            });
            await stream.finalContent();
        } catch (e) { console.error("Share reaction failed", e); }
        setIsBuddyTyping(false);
    };

