            const duplicateKey = Object.keys(currentInbox).find(k => k !== chatId && (k === realId || (currentInbox[k]?.waifu?.name && waifu.name && currentInbox[k].waifu.name.trim().toLowerCase() === waifu.name.trim().toLowerCase())));

            const baseChat = currentInbox[chatId] || { waifu, messages: [] };
            const duplicateChat = duplicateKey ? currentInbox[duplicateKey] : null;

