        if (!chatData) return;
        const waifu = chatData.waifu;

        const originalTags = waifu.original_tags || waifu.tags || [];
        const activeUserName = stateRef.current.useLaylaPersona ? (stateRef.current.userPersona?.name || 'Master') : (stateRef.current.customUserProfile?.name || 'Master');

        // ✨ MIKA'S TOKEN DIET: Feed the Mutation engine ONLY the condensed memory summaries!
        let recentContext = "[NO CHAT HISTORY]";
        const memories = currentMsgs.filter(m => m.memory && m.memory !== 'NONE').slice(-3).map(m => m.memory);
        if (memories.length > 0) {
            recentContext = "[RECENT LORE SUMMARIES]\n" + memories.join('\n');
        } else {
            const recentMsgs = currentMsgs.filter(m => !m.type).slice(-4);
            if (recentMsgs.length > 0) {
                recentContext = "[RECENT CHAT]\n" + recentMsgs.map(m => `${m.role === 'user' ? activeUserName : waifu.name}: ${m.content}`).join('\n');
            }
        }

        let directionRule = "";
        if (direction === 'positive') directionRule = "They have reached SOULBOUND status (Maximum affection/trust). How has this deep bond added to their base tropes?";
        else if (direction === 'negative') directionRule = "They have reached NEMESIS status (Extreme hatred/toxicity). How has this hostility added to their base tropes?";
        else directionRule = "The user has manually triggered a psychological re-evaluation. Based on the recent chat history, what new trait has organically developed?";

