                                                                        const hasForeign = v.tags && v.tags.some(t => fLangs.includes(t.toLowerCase()));
                                                                        const hasEnglish = v.tags && v.tags.some(t => ['english', 'american', 'british', 'en', 'us', 'uk'].includes(t.toLowerCase()));
