                                                                            if (typeof setPreviewWaifu !== 'undefined' && previewWaifu) setPreviewWaifu(updatedWaifu);
                                                                            if (typeof setActiveGroupProfile !== 'undefined' && activeGroupProfile) setActiveGroupProfile(updatedWaifu);
                                                                            if (typeof setInbox !== 'undefined') setInbox(prev => { const next = { ...prev }; const cid = currentWaifu.id; if (next[cid] && !next[cid].isGroup) next[cid].waifu = updatedWaifu; if (typeof activeChatId !== 'undefined' && activeChatId && next[activeChatId]?.isGroup) next[activeChatId].participants = next[activeChatId].participants.map(p => p.id === cid ? updatedWaifu : p); return next; });
                                                                            if (typeof setSessionHistory !== 'undefined') setSessionHistory(prev => prev.map(h => h.waifu.id === currentWaifu.id ? { ...h, waifu: updatedWaifu } : h));
                                                                            if (typeof handleSaveSession !== 'undefined') setTimeout(() => { const tid = typeof sourceChatId !== 'undefined' ? sourceChatId : typeof currentWaifu !== 'undefined' ? currentWaifu.id : typeof updatedWaifu !== 'undefined' ? updatedWaifu.id : typeof waifuId !== 'undefined' ? waifuId : typeof waifu !== 'undefined' ? waifu.id : typeof fullWaifu !== 'undefined' ? fullWaifu.id : typeof targetId !== 'undefined' ? targetId : typeof chatId !== 'undefined' ? chatId : typeof newId !== 'undefined' ? newId : null; handleSaveSession(true, false, tid !== null, tid); }, 500);
