                                    opacity: ((inbox[activeChatId]?.isRpMode || activeDiveByChat[activeChatId]) && !inbox[activeChatId]?.hideRpVisuals) ? 0 : 1,
                                    pointerEvents: ((inbox[activeChatId]?.isRpMode || activeDiveByChat[activeChatId]) && !inbox[activeChatId]?.hideRpVisuals) ? 'none' : 'auto',
                                    transition: 'opacity 0.3s ease',
                                    animation: 'fadeIn 0.3s ease-out'
