                                            border: '1px solid rgba(0, 229, 255, 0.4)', borderBottom: 'none',
                                            borderTopLeftRadius: '6px', borderTopRightRadius: '6px',
                                            zIndex: 25, backdropFilter: 'blur(12px)', WebkitBackdropFilter: 'blur(12px)',
                                            padding: '0 12px', animation: 'fadeIn 0.3s ease',
                                            color: '#00E5FF', fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
                                            fontSize: '9px', fontWeight: 'bold', letterSpacing: '0.05em', textShadow: '0 0 4px rgba(0,229,255,0.5)',
