                    caption: finalTags,
                    lyrics: finalLyrics,
                    duration: finalDuration,
                    lm_batch_size: 1,
                    seed: currentSeed,
                    output_format: enableMp3Compression ? 'mp3' : 'wav16',
                    ...(activeRefData ? { audio_ref: activeRefData, conditioning_strength: audioConfig.conditioning_strength } : {}),
