                    <div className="resume-subtitle" style={{ color: 'rgba(0, 229, 255, 0.4)', fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace", letterSpacing: '0.1em', textAlign: 'center', padding: '0 20px', lineHeight: 1.4 }}>{bootStatusText}</div>
